#!/usr/bin/env node
/**
 * Generates apps/web/src/generated/tool-registry.ts from packages/tools/*.
 *
 * The generated file is gitignored and regenerated automatically by
 * predev / prebuild / pretest / pretypecheck. It is never edited by hand.
 *
 * Each tool directory must contain:
 *   - definition.ts exporting `definition` with a literal `id: '<kebab-case>'`
 *   - index.ts exporting the tool component (lazily imported)
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = fileURLToPath(new URL('..', import.meta.url))
const toolsDir = resolve(repoRoot, 'packages/tools')
const outFile = resolve(repoRoot, 'apps/web/src/generated/tool-registry.ts')

const ID_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
const ID_LITERAL = /^\s*id:\s*['"]([a-z0-9-]+)['"]/m

const entries = readdirSync(toolsDir, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .filter((entry) => !entry.name.startsWith('.') && entry.name !== 'node_modules')
  .map((entry) => entry.name)
  .sort()

const definitions = []
const loaders = []

for (const dir of entries) {
  const definitionFile = resolve(toolsDir, dir, 'definition.ts')
  const indexFile = resolve(toolsDir, dir, 'index.ts')
  const missing = [definitionFile, indexFile].filter((file) => !fileExists(file))
  if (missing.length > 0) {
    throw new Error(
      `[tool-forge] packages/tools/${dir} is missing required files: ${missing
        .map((file) => file.replace(repoRoot, ''))
        .join(', ')}`,
    )
  }

  const source = readFileSync(definitionFile, 'utf8')
  const match = ID_LITERAL.exec(source)
  if (match === null) {
    throw new Error(
      `[tool-forge] cannot find an id literal in packages/tools/${dir}/definition.ts. ` +
        `Expected: id: '<kebab-case>'`,
    )
  }
  const id = match[1]
  if (id !== dir) {
    throw new Error(
      `[tool-forge] packages/tools/${dir}/definition.ts declares id "${id}", ` +
        `which must match the directory name.`,
    )
  }
  if (!ID_PATTERN.test(id)) {
    throw new Error(`[tool-forge] invalid tool id "${id}" in packages/tools/${dir}/definition.ts`)
  }

  const safeName = dir.replace(/[^a-zA-Z0-9_]/g, '_')
  definitions.push(`  definition_${safeName},`)
  loaders.push(`  '${id}': () => import('../../../../packages/tools/${dir}/index'),`)
}

const content = `// GENERATED FILE — do not edit by hand.
// Regenerated by: pnpm tools:gen (runs automatically before dev/build/test/typecheck).
${definitions
  .map(
    (_, i) =>
      `import { definition as definition_${entries[i].replace(/[^a-zA-Z0-9_]/g, '_')} } from '../../../../packages/tools/${entries[i]}/definition'`,
  )
  .join('\n')}

export const toolDefinitions = [
${definitions.join('\n')}
]

export const toolLoaders: Record<string, () => Promise<{ definition: unknown; Tool: unknown }>> = {
${loaders.join('\n')}
}
`

mkdirSync(new URL('.', new URL(`file://${outFile}`)), { recursive: true })
writeFileSync(outFile, content)
console.log(`[tool-forge] generated ${outFile.replace(repoRoot, '')} (${entries.length} tools)`)

function fileExists(file) {
  try {
    readFileSync(file)
    return true
  } catch {
    return false
  }
}
